{
  "requirement_definitions": [
    {
      "id": "DMSR-4915",
      "title": "Re-processing Capacity",
      "text": "The DMS shall provide Processing, Storage, and Network resources capable of executing the DMS Data Release Production over all pre-existing survey data in a time no greater than drProcessingPeriod, without impacting observatory operations."
    },
    {
      "id": "DMSR-9649",
      "title": "Temporary Storage for Communications Links",
      "text": "The infrastructure will provide for temporary storage for a minimum of tempStorageRelMTTR of the mean time to repair of any communications network link at or before the source end of that link."
    },
    {
      "id": "DMSR-6886",
      "title": "Infrastructure Sizing for ”catching up”",
      "text": "The infrastructure will be sized such that after outages, ”catch up” processing of the temporarily stored raw image data may occur at the rate of one night’s observing data processed per day, without interrupting the current day’s observatory operations."
    },
    {
      "id": "DMSR-5747",
      "title": "Incorporate Fault-Tolerance",
      "text": "The infrastructure will incorporate as fault-tolerance features to prevent loss of data in the event of hardware or software failure."
    },
    {
      "id": "DMSR-4278",
      "title": "Incorporate Autonomics",
      "text": "The infrastructure will incorporate suﬃcient capability for self-diagnostics and recovery to provide for continuation of processing in the event of partial hardware or software failures."
    },
    {
      "id": "DMSR-5883",
      "title": "Summit Facility Data Communications",
      "text": "The DMS shall provide data communications infrastructure to accept science data and associated metadata read-outs, and the collection of ancillary and engineering data, for transfer to the base facility."
    },
    {
      "id": "DMSR-4793",
      "title": "Prefer Computing and Storage Down",
      "text": "The DMS computing and storage equipment will be preferentially located at a lower altitude Facility (Base or Archive Center) versus the Summit Facility due to lower support costs and fewer reliability issues. Therefore any processing that can be done in either location will be allocated to a lower altitude Facility."
    },
    {
      "id": "DMSR-5737",
      "title": "DMS Communication with OCS",
      "text": "The DMS at the Base Site shall contain a component to accept control commands from and communicate with the OCS."
    },
    {
      "id": "DMSR-6601",
      "title": "Summit to Base Network",
      "text": "The DMS shall provide communications infrastructure between the Summit Facility and the Base Facility suﬃcient to carry scientiﬁc data and associated metadata for each image in no more than time summToBaseMaxTransferTime."
    },
    {
      "id": "DMSR-6358",
      "title": "Summit to Base Network Availability",
      "text": "The Summit to Base communications shall be highly available, with Mean Time Between Failures (MTBF) > summToBaseNetMTBF."
    }
  ],
